#!/usr/bin/env bash
# GSZ step146 — Netflix TEST sandbox + make Inventory actually deliver.
# (1) Admin "Deliver & notify" now consumes a free inventory unit for
#     source='inventory' plans (so stocked plans deliver — reuses the deliver hook).
# (2) nfMail returns DEMO sample codes for @gsztest.dev sandbox accounts.
# (3) Seeds a "TEST Netflix (Sandbox)" product (clone of Netflix) with all plans
#     as own-inventory (Rs 10) + 3 sandbox stock units each — so you can test
#     every plan/tier end-to-end with NO real account and NO portal calls.
# Patches lib/deliver.js + lib/nfMail.js. Idempotent; robust health check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step146-$TS"; TMP=$(mktemp -d)
PATCHED=(lib/deliver.js lib/nfMail.js)
echo "==> step146: Netflix test sandbox + inventory delivery"
mkdir -p "$BK/lib"; for f in "${PATCHED[@]}"; do cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo ""  | base64 -d > "$TMP/seed.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/lib/deliver.js"; node --check "$GSZ/lib/nfMail.js"
echo "==> seeding test sandbox"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/seed.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""
echo "==> step146 OK ✅  TEST sandbox ready. On the storefront buy '🧪 TEST Netflix (Sandbox)' (Rs 10) — try each plan. Then as admin open the order → 'Deliver & notify customer' with the box BLANK → it pops a sandbox unit. Customer then sees demo codes at Account → Netflix codes, gated by tier (Phone: sign-in+travel · TV: +household · Full: +reset)."
echo "    When done testing: hide/delete the 'TEST Netflix (Sandbox)' product in admin. Sandbox accounts use @gsztest.dev (demo codes only)."
